-- ERP Detroit: Oracle EBS-style conventions
-- Third-party product names below describe the naming-convention style only (nominative use); not affiliated/endorsed. See repo NOTICE.
-- Vendor IDs, item codes, lot IDs, PO numbers in Detroit plant format
SET search_path TO erp_detroit;

CREATE TABLE IF NOT EXISTS suppliers (
    vendor_id VARCHAR(12) PRIMARY KEY,
    company_name VARCHAR(100) NOT NULL,
    quality_rating NUMERIC(4,1),
    status VARCHAR(12) DEFAULT 'ACTIVE',
    payment_terms VARCHAR(20) DEFAULT 'NET30',
    region VARCHAR(30)
);

CREATE TABLE IF NOT EXISTS materials (
    item_code VARCHAR(12) PRIMARY KEY,
    description VARCHAR(100) NOT NULL,
    category VARCHAR(30),
    subcategory VARCHAR(30),
    uom VARCHAR(6),
    vendor_id VARCHAR(12) REFERENCES suppliers(vendor_id),
    lot_id VARCHAR(20),
    receipt_date DATE,
    qa_status VARCHAR(10) DEFAULT 'APPROVED',
    material_grade VARCHAR(30)
);

CREATE TABLE IF NOT EXISTS purchase_orders (
    po_number VARCHAR(20) PRIMARY KEY,
    po_type VARCHAR(10) DEFAULT 'STANDARD',
    item_code VARCHAR(12) REFERENCES materials(item_code),
    plant_code VARCHAR(6) DEFAULT 'DTW',
    quantity NUMERIC(12,3),
    unit_price NUMERIC(12,4),
    total_amount NUMERIC(14,2),
    order_date DATE,
    need_by_date DATE,
    received_date DATE,
    status VARCHAR(12) DEFAULT 'OPEN',
    buyer_name VARCHAR(60),
    ship_to_location VARCHAR(60)
);

-- ============================================================
-- SUPPLIERS (12)
-- ============================================================
ON CONFLICT (vendor_id) DO NOTHING;

-- ============================================================
-- MATERIALS (40)
-- ============================================================
ON CONFLICT (item_code) DO NOTHING;

